struct semaphore {
  int value;          // 可用资源数
  struct PCB *queue;  // 等待队列
};
P(S) {
  S.value = S.value - 1;
  if (S.value < 0) {
    把当前进程插入 S.queue;
    阻塞当前进程;
  }
}
V(S) {
  S.value = S.value + 1;
  if (S.value <= 0) {
    从 S.queue 中移出一个进程 Q;
    唤醒 Q（置为就绪态）;
  }
}

semaphore rmutex = 1, wmutex = 1;
int readcount = 0;
reader() {
  P(rmutex);
  if (readcount == 0) P(wmutex);
  readcount++;
  V(rmutex);
  读文件;
  P(rmutex);
  readcount--;
  if (readcount == 0) V(wmutex);
  V(rmutex);
}
writer() {
  P(wmutex);
  写文件;
  V(wmutex);
}
